"""Reverse Linked List II — reverse the [left, right] window in one pass.

Repeatedly lift the node after `tail` and splice it right behind `prev`.

Time: O(n)   Space: O(1)
"""
if "ListNode" not in globals():
    class ListNode:
        def __init__(self, val=0, next=None):
            self.val = val
            self.next = next


class Solution:
    def reverseBetween(self, head, left: int, right: int):
        if not head or left == right:
            return head
        sentinel = ListNode(0, head)
        prev = sentinel
        for _ in range(left - 1):
            prev = prev.next
        tail = prev.next
        for _ in range(right - left):
            moved = tail.next
            tail.next = moved.next
            moved.next = prev.next
            prev.next = moved
        return sentinel.next
